export type DesignGateApproval = { "gateId": DesignGate; "gateEvaluationRef": ArtifactRef; "authority": "human" | "ai_panel"; "approvalSetRef"?: ArtifactRef; "aiReviewApprovalSetRef"?: ArtifactRef; "approvedAt": string };
export type DesignRendering = { "mediaType": "text/markdown"; "renderedRef": ArtifactRef; "rendererVersion": string; "sourcePacketRef": ArtifactRef; "anchorIds": Array<string> };
export type DesignPrTarget = { "kind": "design_pr"; "repositoryId": string; "subpath": string; "baseBranch": string; "publicationTargetRef": ArtifactRef; "gitChangeId": string; "providerHandle": string; "headCommit": GitOid; "draft": false; "confidential": boolean; "publicationMode": "ordinary" | "private_fork" | "separate_repo"; "securityGroupId"?: string };
