export type DesignDeliveryRecord = { "schemaVersion": "2.0"; "taskId": string; "applicationId": string; "workType": DesignWorkType; "targetKind": "new_application" | "existing_application"; "workflowTemplate": WorkflowTemplateRef; "designProfile": "design-delivery/1.0"; "packetRef": ArtifactRef; "planReviewSubjectRef": ArtifactRef; "subjectHash": Digest; "basis": DesignBasis; "approvals": Array<DesignGateApproval>; "rendering": DesignRendering; "target": DesignDeliveryTarget; "dataClassification": DataClassification; "securityFlagged": boolean; "embargoed": boolean; "securityGroupId"?: string; "approvedAt": string; "approvalsExpireAt": string; "deliveredAt": string; "reviewMode": ReviewMode; "reviewModeDecisionRef"?: ArtifactRef; "reviewMarker"?: "AI-reviewed \u2014 no human review"; "aiReviewApprovalSetRefs"?: Array<ArtifactRef> };
export type DesignBuildBinding = { "schemaVersion": "2.0"; "taskId": string; "designTaskId": string; "designDeliveryRef": ArtifactRef; "packetRef": ArtifactRef; "subjectHash": Digest; "currentBasis": DesignBasis; "result": "reuse" | "replan"; "drift": Array<DesignDrift>; "reopenedSectionIds": Array<PlanSectionId>; "rerequestedGateIds": Array<DesignGate>; "replacementPacketRef"?: ArtifactRef; "evaluatedAt": string };
